code='''def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    r0 = min(r for r, c in pts); r1 = max(r for r, c in pts)
    c0 = min(c for r, c in pts); c1 = max(c for r, c in pts)
    out = [row[:] for row in grid]
    # Complete the outer rectangular frame around the marks.
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            if (r in (r0, r1) or c in (c0, c1)) and out[r][c] == bg:
                out[r][c] = 2
    # Also close single-cell gaps in straight interior runs of marks.
    for r in range(h):
        for c in range(1, w - 1):
            if grid[r][c] == bg and grid[r][c-1] != bg and grid[r][c+1] != bg:
                out[r][c] = 2
    for c in range(w):
        for r in range(1, h - 1):
            if grid[r][c] == bg and grid[r-1][c] != bg and grid[r+1][c] != bg:
                out[r][c] = 2
    return out
'''
